static inline bool f2fs_may_extent_tree(struct inode *inode) /* <=== f2fs_may_extent_tree */ 
{
	if (!test_opt(F2FS_I_SB(inode), EXTENT_CACHE) ||
			is_inode_flag_set(inode, FI_NO_EXTENT))
		return false;

	return S_ISREG(inode->i_mode);
}

